-- 0002_compliance.sql: migracion SQL de lo que APCompliance.migrate creaba en JS.
-- Idempotente (CREATE TABLE IF NOT EXISTS / INSERT OR IGNORE): se puede aplicar sobre cualquier base.
-- Generado de index.html: DDL de migrate(), datos de APCompliance.agents/levels/colombia y de los literales de migrate().

CREATE TABLE IF NOT EXISTS compliance_norms (id TEXT PRIMARY KEY, level INTEGER NOT NULL, name TEXT NOT NULL, source_url TEXT, scope TEXT, rule_key TEXT, rule_value TEXT, demo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS compliance_checks (proposal_id TEXT PRIMARY KEY REFERENCES purchase_proposals(id), status TEXT NOT NULL CHECK(status IN ('pass','review','block')), norm_id TEXT, reason TEXT NOT NULL, checked_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS legal_subagents (id TEXT PRIMARY KEY,name TEXT NOT NULL,subject TEXT NOT NULL,routing TEXT NOT NULL,hierarchy TEXT NOT NULL,configuration_note TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('unconfigured','demo')));
CREATE TABLE IF NOT EXISTS legal_jurisdictions (country TEXT PRIMARY KEY,name TEXT NOT NULL,tax_label TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS labor_cost_entries (id TEXT PRIMARY KEY,country TEXT NOT NULL,period TEXT NOT NULL,structure TEXT NOT NULL CHECK(structure IN ('Fabricación','Comercialización','Servicios')),area TEXT NOT NULL CHECK(area IN ('Operativa','Soporte')),amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),currency TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recruitment_pipeline (id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('Colaboradores internos','Aliados','Productos','Clientes','Mercados')),title TEXT NOT NULL,stage TEXT NOT NULL CHECK(stage IN ('Detectado','Exploración','Evaluación','Incorporación')),note TEXT NOT NULL DEFAULT '',signal TEXT NOT NULL DEFAULT '',demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS candidate_screenings (id TEXT PRIMARY KEY,alias TEXT NOT NULL,role TEXT NOT NULL,evidence TEXT NOT NULL,score INTEGER NOT NULL,explanation TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('review','approved','needs_evidence')),demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payroll_rules (id TEXT PRIMARY KEY,norm_id TEXT NOT NULL,concept TEXT NOT NULL,formula_note TEXT NOT NULL,value_text TEXT,verified_on TEXT,status TEXT NOT NULL);

INSERT OR IGNORE INTO legal_subagents VALUES ('mercantil','Mercantil','Compras, proveedores, operaciones comerciales y sociedades','Propuestas de compra y contratos comerciales','Constitución → legislación mercantil → reglamentos aplicables → actos y decisiones → política interna','Sin fuentes ni reglas de jurisdicción cargadas','unconfigured'),
  ('laboral','Laboral','Vínculos de trabajo, jornada, remuneración y seguridad social','Alta y cambios de personal, nómina, jornada','Constitución → leyes y código laboral → reglamentos → jurisprudencia aplicable → política interna','Caso Colombia disponible solo como demo de fuentes; Venezuela sin fuentes laborales cargadas','demo'),
  ('civil','Civil · contratación','Formación, ejecución, garantías y terminación de contratos civiles','Borradores de contrato, renovaciones y cláusulas','Constitución → legislación civil → reglamentos aplicables → jurisprudencia → cláusulas y política interna','Sin análisis de cláusulas implementado','unconfigured'),
  ('tributario-nacional','Tributario · nacional','IVA, ISLR, aportes parafiscales patronales y tributos sectoriales, según país','Operaciones gravadas, facturación, nómina patronal y declaraciones','Constitución → leyes tributarias → reglamentos → actos administrativos y jurisprudencia → control interno','País y régimen por definir; no se calcula ni declara','unconfigured'),
  ('tributario-regional','Tributario · regional','Tributos de región, estado o departamento según territorio aplicable','Operaciones, establecimientos e inmuebles con nexo regional','Constitución → ley nacional habilitante → norma regional → decisiones aplicables → control interno','Región y competencia por definir','unconfigured'),
  ('tributario-local','Tributario · local','Tributos municipales o distritales según domicilio y actividad','Establecimientos, actividades, inmuebles y permisos locales','Constitución → ley habilitante → ordenanza o acuerdo local → decisiones aplicables → control interno','Municipio y competencia por definir','unconfigured'),
  ('administrativo','Administrativo','Interacciones con entidades públicas y posibles faltas en la actuación de funcionarios, con revisión de hechos y competencia','Quejas o reclamos, peticiones, recursos frente a actos administrativos y eventual responsabilidad estatal','Constitución → procedimiento administrativo y leyes aplicables → reglamentos → acto y expediente → precedentes pertinentes','País, entidad, hechos, plazos y vía competente por verificar; no presenta escritos ni acusa a personas','unconfigured');
